:root {
  --bg-panel: #1a1f2e;
  --bg-header: #222840;
  --bg-room: #2a3050;
  --bg-room-active: #3d5afe;
  --bg-device: #222840;
  --bg-device-on: #1e2d40;
  --bg-footer: #222840;
  --border-room: #3a4060;
  --border-device: #2e3555;
  --border-device-on: #3d5afe;
  --text-title: #ffffff;
  --text-status: #4caf50;
  --text-room: #8892b0;
  --text-room-active: #ffffff;
  --text-device-name: #ccd6f6;
  --text-device-detail: #607090;
  --text-toggle-on: #4caf50;
  --text-toggle-off: #607090;
  --text-stat-val: #ffffff;
  --text-stat-label: #607090;
  --accent-on: #3d5afe;
  --radius-panel: 16px;
  --radius-room: 20px;
  --radius-device: 12px;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.panel {
  background: var(--bg-panel);
  border-radius: var(--radius-panel);
  width: 520px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-header);
  border-radius: 10px;
  padding: 10px 16px;
}

.panel-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-title);
  letter-spacing: 0.3px;
}

.panel-status {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-status);
}

.rooms {
  display: flex;
  gap: 8px;
}

.room {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: var(--radius-room);
  border: 1px solid var(--border-room);
  background: var(--bg-room);
  cursor: pointer;
}

.room.active {
  background: var(--bg-room-active);
  border-color: var(--bg-room-active);
}

.room-icon {
  font-size: 15px;
  line-height: 1;
}

.room-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-room);
}

.room.active .room-name {
  color: var(--text-room-active);
}

.devices {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.device-card {
  background: var(--bg-device);
  border: 1px solid var(--border-device);
  border-radius: var(--radius-device);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.device-card.on {
  background: var(--bg-device-on);
  border-color: var(--border-device-on);
}

.device-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.device-icon {
  font-size: 20px;
  line-height: 1;
}

.toggle {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 6px;
  border-radius: 4px;
}

.on-toggle {
  color: var(--text-toggle-on);
  background: rgba(76, 175, 80, 0.15);
}

.off-toggle {
  color: var(--text-toggle-off);
  background: rgba(96, 112, 144, 0.15);
}

.device-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-device-name);
}

.device-detail {
  font-size: 11px;
  color: var(--text-device-detail);
}

.panel-footer {
  display: flex;
  background: var(--bg-footer);
  border-radius: 10px;
  padding: 10px 0;
}

.stat {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-right: 1px solid var(--border-device);
}

.stat:last-child {
  border-right: none;
}

.stat-val {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-stat-val);
}

.stat-label {
  font-size: 10px;
  color: var(--text-stat-label);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
